import React from 'react';
import { Link } from 'react-router-dom';

export default function ExperienceCard({exp}){
  return (
    <div style={{border:'1px solid #ddd',padding:10}}>
      <img src={exp.media?.[0] || '/placeholder.jpg'} style={{width:'100%',height:150,objectFit:'cover'}} />
      <h3>{exp.title}</h3>
      <p>{exp.description?.slice(0,120)}...</p>
      <p>السعر: ${(exp.price/100).toFixed(2)}</p>
      <Link to={`/experience/${exp._id}`}>تفاصيل</Link>
    </div>
  );
}
